mapper.update:
UPDATE mbr_benefit_version SET state=#{toState},approved_by=COALESCE(#{approvedBy},approved_by),
  effective_at=COALESCE(#{effectiveAt},effective_at),expires_at=COALESCE(#{expiresAt},expires_at),
  revocation_epoch=#{revocationEpoch},version=version+1,updated_at=#{changedAt}
WHERE tenant_id=#{tenantId} AND version_id=#{versionId} AND state=#{fromState} AND version=#{expectedVersion}

mapper.select:
SELECT request_sha256 requestSha256,aggregate_id aggregateId,result_sha256 resultSha256,result_json resultJson
FROM mbr_benefit_command
WHERE tenant_id=#{tenantId} AND command_type=#{commandType} AND idempotency_key=#{idempotencyKey}
